M004 changes the status for a cursor that is not a string. The spec says a cursor that was not issued to the caller gives 400, and cursors are strings, so any non-string value was never issued. That behavior is determined, so I added tests for it.

I ignored M005. It changes the status for an empty or non-string idempotency key, and the spec never says how `pay` treats such a key. The spec's 400 for `pay` covers only an invalid amount, so a test there would encode implementation behavior.

```python file=test_phase_b_mutants.py
from hypothesis import given, settings, strategies as st

from solution import Service


class Clock:
    def __init__(self, t=1000.0):
        self.t = t

    def now(self):
        return self.t


class NullGateway:
    def charge(self, reference, amount_cents):
        return None


def _setup(n_docs=3):
    svc = Service(Clock(), NullGateway())
    assert svc.register("alice", "password1")[0] == 201
    tok = svc.login("alice", "password1")[1]["token"]
    for i in range(n_docs):
        assert svc.create_document(tok, f"d{i}", "c")[0] == 201
    return svc, tok


def test_non_string_cursor_examples_give_400():
    """A cursor that was never issued to the caller, including a non-string value, gives 400."""
    svc, tok = _setup()
    for cursor in (123, 0, 1, 1.5, b"abc", True):
        out = svc.list_documents(tok, page_size=1, cursor=cursor)
        assert out[0] == 400, f"cursor={cursor!r} output={out!r}"


@settings(max_examples=50, deadline=None)
@given(
    cursor=st.one_of(st.integers(), st.floats(allow_nan=False), st.binary()),
    page_size=st.integers(1, 100),
)
def test_non_string_cursor_property_gives_400(cursor, page_size):
    """Any cursor value that is not an issued cursor gives 400 for any valid page size."""
    svc, tok = _setup()
    out = svc.list_documents(tok, page_size=page_size, cursor=cursor)
    assert out[0] == 400, f"cursor={cursor!r} page_size={page_size!r} output={out!r}"


def test_non_string_cursor_does_not_break_later_valid_paging():
    """A rejected cursor does not prevent following a genuinely issued cursor afterwards."""
    svc, tok = _setup(3)
    first = svc.list_documents(tok, page_size=1)
    assert first[0] == 200 and first[1]["next_cursor"] is not None, f"output={first!r}"
    bad = svc.list_documents(tok, page_size=1, cursor=42)
    assert bad[0] == 400, f"cursor=42 output={bad!r}"
    nxt = svc.list_documents(tok, page_size=1, cursor=first[1]["next_cursor"])
    assert nxt[0] == 200, f"cursor={first[1]['next_cursor']!r} output={nxt!r}"
```

