import sys
import types

from hypothesis import given, settings, strategies as st


try:
    from gateway import GatewayTimeout
except Exception:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass

    gateway_module = types.ModuleType("gateway")
    gateway_module.GatewayTimeout = GatewayTimeout
    sys.modules["gateway"] = gateway_module


class FakeClock:
    def __init__(self, t=0.0):
        self.t = float(t)

    def now(self):
        return self.t


class RecordingGateway:
    def __init__(self):
        self.calls = []

    def charge(self, reference, amount_cents):
        self.calls.append((reference, amount_cents))


def register_and_login(service, username="alice", password="password123"):
    out = service.register(username, password)
    assert out[0] == 201, f"input={(username, password)!r} output={out!r}"
    out = service.login(username, password)
    assert out[0] == 200, f"input={(username, password)!r} output={out!r}"
    return out[1]["token"]


@given(cursor=st.integers())
@settings(max_examples=25)
def test_non_string_listing_cursor_is_not_issued_to_caller_and_returns_400(cursor):
    """A list_documents cursor that was not issued to the caller must return 400."""
    from solution import Service

    service = Service(FakeClock(0.0), RecordingGateway())
    token = register_and_login(service)

    out = service.list_documents(token, page_size=1, cursor=cursor)
    assert out[0] == 400, f"input={(token, 1, cursor)!r} output={out!r}"


def test_pay_with_empty_idempotency_key_returns_only_a_specified_pay_status():
    """The pay method must return only one of the statuses specified for pay for every in-process call."""
    from solution import Service

    service = Service(FakeClock(0.0), RecordingGateway())
    token = register_and_login(service)
    allowed_statuses = {200, 201, 400, 401, 409, 504}

    out = service.pay(token, 1, "")
    assert out[0] in allowed_statuses, f"input={(token, 1, '')!r} output={out!r}"
